#!/usr/bin/env node
// Condense a conversation JSONL into a readable digest.
import { createInterface } from 'node:readline';

const MAXTXT = Number(process.env.MAXTXT || 1200);
const MAXTOOL = Number(process.env.MAXTOOL || 220);
const clip = (s, n) => {
  s = String(s ?? '').replace(/\s+/g, ' ').trim();
  return s.length > n ? s.slice(0, n) + ' …[+' + (s.length - n) + ']' : s;
};

const rl = createInterface({ input: process.stdin, crlfDelay: Infinity });
let i = 0;
for await (const line of rl) {
  if (!line.trim()) continue;
  let e;
  try { e = JSON.parse(line); } catch { continue; }
  i++;
  const ts = (e.timestamp || '').replace('T', ' ').replace(/\..*/, '');
  const m = e.message;
  if (e.attachment) {
    console.log(`[${i}] ${ts} ATTACH(${e.attachment.type || ''}/${e.attachment.hookName || ''}) ${clip(e.attachment.stdout || e.attachment.content || '', 300)}`);
    continue;
  }
  if (!m) { console.log(`[${i}] ${ts} <${e.type || 'entry'}>`); continue; }
  const role = m.role || e.type;
  const content = Array.isArray(m.content) ? m.content : [{ type: 'text', text: m.content }];
  for (const c of content) {
    if (c.type === 'text') {
      if (c.text && c.text.trim()) console.log(`[${i}] ${ts} ${role.toUpperCase()}: ${clip(c.text, MAXTXT)}`);
    } else if (c.type === 'thinking') {
      console.log(`[${i}] ${ts} THINK: ${clip(c.thinking, 400)}`);
    } else if (c.type === 'tool_use') {
      console.log(`[${i}] ${ts} TOOL ${c.name}: ${clip(JSON.stringify(c.input), MAXTOOL)}`);
    } else if (c.type === 'tool_result') {
      const err = c.is_error ? ' ERROR' : '';
      const body = typeof c.content === 'string' ? c.content : JSON.stringify(c.content);
      console.log(`[${i}] ${ts} RESULT${err}: ${clip(body, c.is_error ? 500 : 200)}`);
    }
  }
}

